Import ListNotations. Import AX2. Import AX2B. Import AX2S.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

Module Z0 := Cut_strapp_zero_xboth.  Module Z0T := Cut_strapp_zero_xboth_T.
Module F := Cut_strapp_fast_xboth.   Module FT := Cut_strapp_fast_xboth_T.
Module GA := Cut_strapp_growa_xboth. Module GAT := Cut_strapp_growa_xboth_T.
Module GB := Cut_strapp_growb_xboth. Module GBT := Cut_strapp_growb_xboth_T.
Abbreviation RSEGS := Pm5PlanKit.RSEGS.

Module SAA.
Definition PC_OPNEW : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!1,0|D5cef0;").    (* [comment removed for export] *)
Definition PC_MM : Z := 527112.        (* [comment removed for export] *)
Definition PC_MC : Z := 527116.        (* [comment removed for export] *)
Definition PC_OPDEL : Z := 1046256.     (* [comment removed for export] *)
Definition RETPC : Z := 1055668.        (* [comment removed for export] *)
Definition SBz : Z := 2147450880.
(* [comment removed for export] *)
Definition NORM (e : expr) : expr := unlin (lin_of e).
Definition SAK (e : expr) : saddr := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S10!1+8!2+9+7+1$e;R+1&l;R!1'2#1'3!2,4!1'5!4,6+70,:!3';+70#1!3'<+70#1").
Definition oE := EVar 10. Definition qE := EVar 11. Definition kE := EVar 32. Definition pE := EVar 34. Definition nbE := EVar 44.
Definition CAP : expr := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3,=,>!1,?!1,0|10;'@").                                                    (* [comment removed for export] *)
Definition W0OLD : expr := EAlu Instr.ALU_ADD CAP (ELit 1).
(* [comment removed for export] *)
Definition szE := EVar 33. Definition nE := EVar 12.
Definition PSZ : expr := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10}Q!3,A,B!1,C0!1,C}R").                                       (* [comment removed for export] *)
Definition SZN_F : expr := Eval vm_compute in NORM (APC.eadd szE nE).                                     (* [comment removed for export] *)
Definition NUL_F : saddr := Eval vm_compute in SAK (APC.eadd (APC.eadd szE nE) pE).
Definition NUL_Z : saddr := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10}Q!2,4!3,A,B!1,C0!1,C}R,:").
Definition STAT : list kentry := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3,D+E!2,F'G'H!3,D+E!3,I!2,4!1,?,:!1,0|D6d7b8;}8!1,?'J!1,K+E").
Definition NEWS_F : list kentry := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3'L+E'M!3,D+E!3,N!2,4'O,:'P}1!1,K+E").
Definition BOLD : list (expr * expr) := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!2+9+1+1!3,D0!4,6+1+1'Q'R!1,K0").
Definition CP0 : list SGP.region := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!2+9+1+7!2+90+1|<110;!3,D1!4,60+1!4,6+1+7!1,C}2!1,S2!1,?!1,02!3,D1!4,60+1!4,6+1+7'T,:!1,?!1,0|48;!3,D1!4,60+1!4,6+1+7'Q,:'R!1,K1").      (* [comment removed for export] *)
Definition CPG0 : list SGP.region := [(EVar 2, -4368, ELit 4368); (oE, 0, ELit 24)].                   (* [comment removed for export] *)
Definition FFS_Z : list (list (expr * Z * Z)) := map (fun _ => []) Z0.CPS.
Definition FFS_F : list (list (expr * Z * Z)) := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!2+9!2+9+1+7+7!4'U+V!1+80$~R+V!1,K0'W").
Definition isSome {A} (o : option A) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S01<scd;$A;R{cd;$o;R!1+X#1-XRN$o;R!1+X#2+Y#12$a;R#2,Z,[").
Definition has := CC.has_cell.
Definition news_of (nb : nat) (cj : CC.cutpoint) : list kentry := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$nb;R+\$cj;R+V!3'^0+E$X;R+E!1'^1!2'^2#3#1!1'^3#1").
(* [comment removed for export] *)
Definition leaf_chk_z (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      (Z.eqb pc RETPC && Nat.eqb i 0 && CBA.exit_base_chk Z0T.NF RETPC c ps && CHA.foot_chk Z0T.NF Z0.HDECL c BOLD [] && CH2.blocks_eqb (nth i Z0.BLS []) BOLD
       && CBA.regions_eqb (CC.cp_F c) CP0 && Nat.leb 40 (CC.cp_nx c)
       && has cells (KWord (SA oE 0) 8 W0OLD) && has cells (KWord (SA oE 8) 8 szE) && has cells (KWord (SA oE 16) 8 pE)
       && has cells (KBlob (SA pE 0) szE 0) && has cells (KWord NUL_Z 1 (ELit 0)) && has cells (KRange nE 0 0))%bool
  end.
(* [comment removed for export] *)
Definition leaf_chk_f (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      match CH2.ret_of F.RETS i k with
      | Some j =>
          match nth_error F.CPS j with
          | Some cj =>
              (Z.eqb pc PC_MM && Z.eqb (SR.ps_pc ps) PC_MM && Nat.eqb i 0 && Nat.eqb j 1 && CH2.blocks_eqb (nth i F.BLS []) BOLD && CH2.blocks_eqb (nth j F.BLS []) BOLD
               && CHA.foot_chk FT.NF F.HDECL c BOLD [] && CBA.regions_eqb (CC.cp_F c) CP0
               && isSome (CHA.custom_chk FT.NF F.HDECL FT.SCELLS FT.GLO FT.GHI 2560 0 BOLD [] [(PSZ, 0, nE)] NEWS_F (Some PSZ) c ps cj BOLD [] BOLD [])
               && CL.ps_reg_is ps 10 PSZ && CL.ps_reg_is ps 11 qE && CL.ps_reg_is ps 12 nE && has cells (KBlob (SA qE 0) nE 1))%bool
          | None => false
          end
      | None =>
          (Z.eqb pc RETPC && Nat.eqb i 1 && CBA.exit_base_chk FT.NF RETPC c ps && CHA.foot_chk FT.NF F.HDECL c BOLD [] && CH2.blocks_eqb (nth i F.BLS []) BOLD
           && CBA.regions_eqb (CC.cp_F c) CP0 && Nat.leb 40 (CC.cp_nx c)
           && has cells (KWord (SA oE 0) 8 W0OLD) && has cells (KWord (SA oE 8) 8 SZN_F) && has cells (KWord (SA oE 16) 8 pE)
           && has cells (KBlob (SA pE 0) szE 0) && has cells (KBlob (SA PSZ 0) nE 1) && has cells (KWord NUL_F 1 (ELit 0)))%bool
      end
  end.
Lemma leaf_z_ok : CH2.leaves_all Z0.CPS Z0.TAGS leaf_chk_z = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,^4+Y,Z!3+^5+Y!3'^6'^7'^8'^9,Z").
Qed.
Lemma leaf_f_ok : CH2.leaves_all F.CPS F.TAGS leaf_chk_f = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,^4+Y,Z!3+^5+Y!3'^6'W'^:'^;,Z").
Qed.
Lemma heap_z_ok : CHA.heap_chkA Z0T.NF Z0.HDECL Z0.BLS FFS_Z Z0.CPS Z0.TAGS = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,^4+Y,Z!3+^5+Y!6'^<'^='^>'^?'^@'^7'^8,Z").
