(* [comment removed for export] *)
Lemma append_zero : forall (LB : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (o cap p sp r : Z) (s : list Z),
  PMSA.cps_asan L ar HI 1055420 r sp PMSA.STR_SCR LB FF LK cr A 0
      (fun R M => PMSA.a0 R o /\ PMSA.a2 R 0 /\
                  PMSA.str_at L M o (PML.SLong cap p s) /\ 24 <= cap /\ In (p, cap) LB /\ shadow_blk M p cap /\ PMSA.fobj M FF o 24 /\ PMSA.stksh ar M sp PMSA.STR_SCR /\
